import{_ as i,k as a,A as t,a6 as l,E as n,j as h}from"./chunks/framework.Bul4SA1j.js";const g=JSON.parse('{"title":"v1.35.0","description":"The changelog for v1.35.0.","frontmatter":{"title":"v1.35.0","page_title":"v1.35.0 Changelog","description":"The changelog for v1.35.0.","category":"Releases","mentions":["Andexter8"]},"headers":[{"level":2,"title":"Additions","slug":"additions","link":"#additions","children":[{"level":3,"title":"Commands","slug":"commands","link":"#commands","children":[]},{"level":3,"title":"Settings","slug":"settings","link":"#settings","children":[]},{"level":3,"title":"Ultra Security Mode","slug":"ultra-security-mode","link":"#ultra-security-mode","children":[{"level":4,"title":"Permissions","slug":"permissions","link":"#permissions","children":[]}]}]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"Commands","slug":"commands-1","link":"#commands-1","children":[]},{"level":3,"title":"Settings","slug":"settings-1","link":"#settings-1","children":[]},{"level":3,"title":"Teleport Systems","slug":"teleport-systems","link":"#teleport-systems","children":[]},{"level":3,"title":"TPA System","slug":"tpa-system","link":"#tpa-system","children":[]},{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]}]},{"level":2,"title":"Removals","slug":"removals","link":"#removals","children":[{"level":3,"title":"Settings","slug":"settings-2","link":"#settings-2","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Commands","slug":"commands-2","link":"#commands-2","children":[]},{"level":3,"title":"Entities","slug":"entities","link":"#entities","children":[]},{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Technical Additions","slug":"technical-additions","link":"#technical-additions","children":[{"level":3,"title":"API","slug":"api","link":"#api","children":[{"level":4,"title":"cmdutils Module","slug":"cmdutils-module","link":"#cmdutils-module","children":[]},{"level":4,"title":"Config","slug":"config","link":"#config","children":[]}]}]},{"level":2,"title":"Technical Changes","slug":"technical-changes","link":"#technical-changes","children":[{"level":3,"title":"API","slug":"api-1","link":"#api-1","children":[{"level":4,"title":"cmdutils Module","slug":"cmdutils-module-1","link":"#cmdutils-module-1","children":[]},{"level":4,"title":"Config","slug":"config-1","link":"#config-1","children":[]}]}]},{"level":2,"title":"Technical Fixes","slug":"technical-fixes","link":"#technical-fixes","children":[{"level":3,"title":"Commands","slug":"commands-3","link":"#commands-3","children":[]}]}],"relativePath":"changelogs/v1.35.0.md","filePath":"changelogs/v1.35.0.md"}'),o={name:"changelogs/v1.35.0.md"};function d(r,e,c,m,p,u){const s=n("template-Stub");return h(),a("div",null,[t(s),e[0]||(e[0]=l('<p><strong>Renamed the add-on from <code class="shiki"><span>8Crafter&#39;s Debug Sticks, Chat Ranks, Custom UI, JavaScript Commands/Script REPL, and Server Utilities</span></code> to <code class="shiki"><span>8Crafter&#39;s Server Utilities &amp; Debug Sticks</span></code>!</strong></p><h2 id="additions" tabindex="-1">Additions <a class="header-anchor" href="#additions" aria-label="Permalink to &quot;Additions&quot;">​</a></h2><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Added the <a href="./../commands-list/--loadchunks.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\loadchunks</span></code></a> command. It has one alias: <code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\lc</span></code>.</li><li>Added the <code class="shiki"><span>duration</span></code> parameter to the <a href="./../commands-list/-selectionrender.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\selectionrender</span></code></a> command.</li><li>Added the <code class="shiki"><span>t</span></code> flag to the <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command. This flag causes the command to create ghost items if the slot type is a number or <code class="shiki"><span>~</span></code>.</li><li>Added the <a href="./../commands-list/-tpaccept.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpaccept</span></code></a> command.</li><li>Added the <a href="./../commands-list/-tpdeny.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpdeny</span></code></a> command.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Added the <a href="./../settings/script.html#default-min-ms-between-tick-waits"><code class="shiki"><span>Default Min MS Between Tick Waits</span></code></a> setting <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#defaultminmsbetweentickwaits" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">defaultMinMsBetweenTickWaits</span></code></a> to the <a href="./../settings/script.html">Script Settings</a> menu.</li><li>Added 4 new options related to the console and chat logs about whether or not a compatible version of the <a href="/andexdb/../main/add-ons/bluemods-anticheat.html">BlueMods Anticheat</a> add-on is on the world to the <a href="./../settings/script.html">Script Settings</a> menu.</li></ul><h3 id="ultra-security-mode" tabindex="-1">Ultra Security Mode <a class="header-anchor" href="#ultra-security-mode" aria-label="Permalink to &quot;Ultra Security Mode&quot;">​</a></h3><h4 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h4><ul><li>Added the <code class="shiki"><span>andexdb.bypassTeleportCooldowns</span></code> permission to Ultra Security Mode.</li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="commands-1" tabindex="-1">Commands <a class="header-anchor" href="#commands-1" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>The <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command now no longer creates ghost items, unless the new <code class="shiki"><span>t</span></code> flag is used and the slot type is a number or <code class="shiki"><span>~</span></code>.</li><li>The <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command now takes a target selector instead of a player name.</li><li>The <a href="./../commands-list/-copyitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitem</span></code></a> command now takes a target selector instead of a player name.</li><li>The <a href="./../commands-list/-copyitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitem</span></code></a> command now allows for multiple targets.</li><li>The <a href="./../commands-list/-tpa.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpa</span></code></a> command now uses the new <a href="./../systems/tpa.html">TPA system</a>.</li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Massive overhaul to the <a href="./../settings/script.html">Script Settings</a> menu.</li></ul><h3 id="teleport-systems" tabindex="-1">Teleport Systems <a class="header-anchor" href="#teleport-systems" aria-label="Permalink to &quot;Teleport Systems&quot;">​</a></h3><ul><li>Made it so if Ultra Security Mode is enabled, players with the <code class="shiki"><span>andexdb.bypassTeleportCooldowns</span></code> permission can bypass the countdown and cooldown for teleports with things such as the homes and warps systems, and if Ultra Security Mode is disabled, then players with the <code class="shiki"><span>admin</span></code> tag can bypass it.</li></ul><h3 id="tpa-system" tabindex="-1">TPA System <a class="header-anchor" href="#tpa-system" aria-label="Permalink to &quot;TPA System&quot;">​</a></h3><ul><li>The <a href="./../systems/tpa.html">TPA system</a> is no longer experimental.</li></ul><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Added menus for resetting player and preset permissions in Ultra Security Mode.</li></ul><h2 id="removals" tabindex="-1">Removals <a class="header-anchor" href="#removals" aria-label="Permalink to &quot;Removals&quot;">​</a></h2><h3 id="settings-2" tabindex="-1">Settings <a class="header-anchor" href="#settings-2" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Removed the <a href="./../settings/script.html#protected-areas-refresh-rate"><code class="shiki"><span>Protected Areas Refresh Rate</span></code></a> option from the <a href="./../settings/script.html">Script Settings</a> menu.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="commands-2" tabindex="-1">Commands <a class="header-anchor" href="#commands-2" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed the <a href="./../commands-list/-swapitems.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\swapitems</span></code></a> command.</li><li>Fixed the <a href="./../commands-list/-copyitemfrom.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitemfrom</span></code></a> command.</li></ul><h3 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="./../entities/tickingarea_6.html"><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">andexdb:tickingarea_6</span></code></a> entity could not be made visible if <a href="/andexdb/../main/add-ons/entity-scale.html">Entity Scale</a> was not on the world.</li></ul><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the Manage Bans menu used <a href="./../settings/ui.html#max-players-per-manage-players-page"><code class="shiki"><span>config.ui.pages.maxPlayersPerManagePlayersPage</span></code></a> instead of <a href="./../settings/ui.html#max-bans-per-manage-bans-page"><code class="shiki"><span>config.ui.pages.maxBansPerManageBansPage</span></code></a> for the number of entries per page.</li><li>Fixed a bug where the Bounties Placed By Me menu still used the old UI style.</li><li>Fixed a bug where the Individual Bounties menu still used the old UI style.</li><li>Fixed a bug where the Home Details menu still used the old UI style.</li><li>Fixed a bug where the New Home menu still used the old UI style.</li><li>Fixed a bug where the Ultra Security Mode Debug menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions Presets menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions for Player/Preset menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions for Player/Preset menu had yellow labels for permissions that were enabled on the everyone preset, when editing the permissions for a preset.</li><li>Fixed a bug where the Place Bounty menu threw an error when the player had already placed a bounty on the target, now it shows a warning instead, saying that to do it, they will have to remove the previous bounty first, and it provides and option to do so.</li><li>Fixed a bug where the icon for the View Individual Bounties button was an arrow pointing left instead of right.</li><li>Fixed bugs with the player and server shop systems where some of the menus had not yet been updated to the new UI style.</li><li>Fixed a bug where the edit warp menu was called <code class="shiki"><span>New Warp</span></code> instead of <code class="shiki"><span>Edit Warp</span></code>.</li></ul><h2 id="technical-additions" tabindex="-1">Technical Additions <a class="header-anchor" href="#technical-additions" aria-label="Permalink to &quot;Technical Additions&quot;">​</a></h2><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><h4 id="cmdutils-module" tabindex="-1">cmdutils Module <a class="header-anchor" href="#cmdutils-module" aria-label="Permalink to &quot;cmdutils Module&quot;">​</a></h4><ul><li>Added <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.getItemFromParsedSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">getItemFromParsedSlot</span></code></a></li></ul><h4 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h4><ul><li>Added <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#defaultminmsbetweentickwaits" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">defaultMinMSBetweenTickWaits</span></code></a>.</li></ul><h2 id="technical-changes" tabindex="-1">Technical Changes <a class="header-anchor" href="#technical-changes" aria-label="Permalink to &quot;Technical Changes&quot;">​</a></h2><ul><li>When Entity Scale or BlueMods Anticheat are not detected upon startup, the add-on will now tell you in the console as a warning, rather than a log, so that you don&#39;t have to change your log level to see it.</li></ul><h3 id="api-1" tabindex="-1">API <a class="header-anchor" href="#api-1" aria-label="Permalink to &quot;API&quot;">​</a></h3><h4 id="cmdutils-module-1" tabindex="-1">cmdutils Module <a class="header-anchor" href="#cmdutils-module-1" aria-label="Permalink to &quot;cmdutils Module&quot;">​</a></h4><ul><li>Massive performance improvements to the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.getSlotFromParsedSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">getSlotFromParsedSlot</span></code></a> function.</li><li>Massive performance improvements to the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.parseSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">parseSlot</span></code></a> function.</li></ul><h4 id="config-1" tabindex="-1">Config <a class="header-anchor" href="#config-1" aria-label="Permalink to &quot;Config&quot;">​</a></h4><ul><li>Deprecated <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#protectedareasrefreshrate" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">protectedAreasRefreshRate</span></code></a>.</li></ul><h2 id="technical-fixes" tabindex="-1">Technical Fixes <a class="header-anchor" href="#technical-fixes" aria-label="Permalink to &quot;Technical Fixes&quot;">​</a></h2><h3 id="commands-3" tabindex="-1">Commands <a class="header-anchor" href="#commands-3" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed a bug where some of the chat commands were using <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.modules.cmds.executeCommandPlayerW.html#sendmessageb" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">executeCommandPlayerW</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">sendMessageB</span></code></a> to send errors instead of <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.modules.cmds.executeCommandPlayerW.html#senderror" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">executeCommandPlayerW</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">sendError</span></code></a>.</li></ul>',46))])}const f=i(o,[["render",d]]);export{g as __pageData,f as default};
